full_types.values_compute:
@ShielddSecurity.SourceGraphEvaluation.values_compute : ∀ {F : Type} [inst : Field.{0} F] {inputs nodes : Nat}
  (graph : ShielddSecurity.Compiler.SourceGraph inputs nodes) (inputValues : Nat → F) (index : Fin nodes),
  @Eq.{1} F (@ShielddSecurity.SourceGraphEvaluation.values F inst inputs nodes graph inputValues index)
    (@ShielddSecurity.Compiler.sourceValue F inst (@Fin.val nodes index) inputValues
      (@ShielddSecurity.Compiler.SourceGraph.prior inputs nodes graph F
        (@ShielddSecurity.SourceGraphEvaluation.values F inst inputs nodes graph inputValues) index)
      (@ShielddSecurity.Compiler.SourceGraph.node inputs nodes graph index))

