@ShielddSecurity.SourceGraphEvaluation.computing_values_exist : ∀ {F : Type} [inst : Field.{0} F] {inputs nodes : Nat}
  (graph : ShielddSecurity.Compiler.SourceGraph inputs nodes) (inputValues : Nat → F),
  @Exists.{1} (Fin nodes → F) fun (computed : Fin nodes → F) =>
    And
      (∀ (index : Fin nodes),
        @Eq.{1} F (computed index)
          (@ShielddSecurity.Compiler.sourceValue F inst (@Fin.val nodes index) inputValues
            (@ShielddSecurity.Compiler.SourceGraph.prior inputs nodes graph F computed index)
            (@ShielddSecurity.Compiler.SourceGraph.node inputs nodes graph index)))
      (∀ (reference : Fin nodes → F),
        (∀ (index : Fin nodes),
            @Eq.{1} F (reference index)
              (@ShielddSecurity.Compiler.sourceValue F inst (@Fin.val nodes index) inputValues
                (@ShielddSecurity.Compiler.SourceGraph.prior inputs nodes graph F reference index)
                (@ShielddSecurity.Compiler.SourceGraph.node inputs nodes graph index))) →
          @Eq.{1} (Fin nodes → F) computed reference)
